#include <stdio.h>
struct Record { char flag; int value; };
int main(void) {
 printf("size=%zu\n", sizeof(struct Record));
 printf("offset(value)=%zu\n", offsetof(struct Record, value));
 return 0;
}

#include <stddef.h>
#include <stdio.h>
